package Arrays;

public class Reverse_array {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
        int a[]=new int[5];
        a[0]=10;
        a[1]=20;
        a[2]=30;
        a[3]=40;
        a[4]=50;
        for(int x=a.length-1;x>=0;x--)
        {
        	System.out.println(a[x]);
        }
        
	}

}
